function record(id,key,text){if(key==='storage'||key==='topic')return;if(['locationStaff','locationLab','time','storage','patrol'].includes(key))addRumor(key,text,id);let arr=relationFacts[id]||(relationFacts[id]=[]);if(!arr.some(f=>f.key===key))arr.push({key,text,status:['martin','planning'].includes(key)?'confirmé':'rapporté'});saveCampaign()}
function addRumor(key,text,source,subject='',reportable=false){let r=rumors.find(r=>r.key===key);if(r){r.sources=[...new Set([...(r.sources||[r.source]),source])];r.reportable=r.reportable||reportable}else rumors.push({key,text,source,sources:[source],subject,reportable,status:'À vérifier',reported:false});saveCampaign()}
function mergeRumors(){let old=rumors;rumors=[];for(let r of old){if(r.key==='storage')continue;let found=rumors.find(v=>v.key===r.key);if(found)found.sources=[...new Set([...found.sources,...(r.sources||[r.source])])];else rumors.push({...r,sources:r.sources||[r.source]})}}
function verify(key,valid,correction=''){for(let r of rumors)if(r.key===key){r.status=valid?'Confirmée':'Fausse';if(correction)r.correction=correction}for(const arr of Object.values(relationFacts))for(const f of arr)if(f.key===key){f.status=valid?'confirmé':'faux';if(!valid&&correction)f.text=correction}saveCampaign()}
