const periodBounds={attente:[450,465],entree:[465,475],rang1:[475,480],cours1:[480,590],recre1:[590,605],rang2:[605,610],cours2:[610,720],midiBefore:[720,750],lunchRank:[750,755],lunchMeal:[755,785],midiAfter:[785,840],cours3:[840,890],recre2:[890,905],rang3:[905,910],cours4:[910,960],controle:[960,1020]};
function postsFor(p){let old=staffSchedule[p],expected=['attente','entree'].includes(p)?['gate','yard1','yard2']:['yard1','yard2','patrol'];if(!old||Object.values(old).includes('life')||expected.some(label=>!Object.values(old).includes(label))){let pool=[...supervisorIds];for(let i=pool.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}staffSchedule[p]=Object.fromEntries(pool.map((id,i)=>[id,expected[i]]));saveCampaign()}return staffSchedule[p]}
function patrolAt(v){let p=phaseAt(v),bounds=periodBounds[p];if(!bounds||bounds[1]-bounds[0]<12||v<480)return null;let posts=postsFor(p),assigned=supervisorIds.find(id=>posts[id]==='patrol');if(!(p in patrolSchedule)||(patrolSchedule[p]?.id&&patrolSchedule[p].id!==assigned)){patrolSchedule[p]=Math.random()<.72?{id:assigned,start:bounds[0]+2,end:Math.min(bounds[1]-1,bounds[0]+17)}:null;saveCampaign()}let item=patrolSchedule[p];return item&&v>=item.start&&v<item.end?item:null}
function patrolPosition(v){let event=patrolAt(v);if(!event)return null;let f=(v-event.start)/(event.end-event.start);return scene==='inside'?{x:320+Math.sin(f*Math.PI*2)*7,y:330+f*570}:scene==='insideNorth'?{x:100+f*1330,y:286+Math.sin(f*Math.PI*2)*4}:{x:2040+Math.sin(f*Math.PI*2)*42,y:1660-1120*f}}
function lifeSupervisor(){let p=phaseAt(t),posts=postsFor(p),id=supervisorIds.find(x=>posts[x]==='patrol')||supervisorIds.find(x=>posts[x]==='yard1');return id?npcs.find(n=>n.id===id):null}
