function clock(){let h=Math.floor(t/60),m=Math.floor(t%60);return `${h} h ${String(m).padStart(2,'0')}`}
function phaseAt(v){if(v<465)return 'attente';if(v<475)return 'entree';if(v<480)return 'rang1';if(v<590)return 'cours1';if(v<605)return 'recre1';if(v<610)return 'rang2';if(v<720)return 'cours2';if(v<750)return 'midiBefore';if(v<755)return 'lunchRank';if(v<785)return 'lunchMeal';if(v<840)return 'midiAfter';if(v<890)return 'cours3';if(v<905)return 'recre2';if(v<910)return 'rang3';if(v<960)return 'cours4';if(v<1020)return 'controle';return 'fin'}
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';toastUntil=performance.now()+4100}function updateHUD(){$('#clock').textContent=clock();$('#objective').textContent=t<960?'Contrôle de maths · 16 h à 17 h':t<1020?'Contrôle en cours · fin à 17 h':'Journée terminée';$('#hint').textContent=scene.startsWith('inside')?'Clique sur les couloirs pour marcher · Clique sur une porte · M : carte (pause)':'Clique pour marcher et parler · Clique sur le hall pour entrer · M : carte (pause)'}
function chance(base){return Math.max(10,Math.min(95,base+skills.discretion*8))}function act(label,p,fn){return [label+' · '+p+' %',()=>{let ok=Math.random()*100<p;fn(ok);skills.discretion=Math.min(5,skills.discretion+(ok?.3:.15));renderSkills()}]}
function renderSkills(){$('#skills').textContent=Object.entries(skills).filter(([,n])=>n>0).map(([k,n])=>`${k==='discretion'?'Discrétion':k==='relation'?'Relations':'Études'} ${n.toFixed(1)}`).join(' · ')}
