function building(z,roof='#c07c60'){rect(z.x+16,z.y+18,z.w,z.h,'#19384477');rect(z.x,z.y,z.w,z.h,'#e5d0ae');rect(z.x+12,z.y+12,z.w-24,z.h-24,roof);for(let i=0;i<Math.floor(z.w/100);i++){rect(z.x+36+i*98,z.y+45,52,50,'#759ca5');rect(z.x+42+i*98,z.y+51,40,38,'#b6dcce')}rect(z.x+z.w/2-55,z.y+z.h-28,110,35,'#efcd88');label(z.name,z.x+z.w/2,z.y+z.h/2,27,'#243f49')}
const courtyardFloor=new Image();courtyardFloor.src='cour-exterieure.png';
function outside(){
  if(courtyardFloor.complete&&courtyardFloor.naturalWidth){ctx.drawImage(courtyardFloor,0,0,WORLD.w,2000);rect(0,2000,WORLD.w,240,'#384d5b')}else rect(0,0,WORLD.w,WORLD.h,'#7b9c77');
  // Sol, cheminements, lignes de cour.
  // Le portail dynamique reprend l’emplacement du portail de l’image approuvée.
  ctx.strokeStyle='#456c6f';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(180,1605);ctx.lineTo(1110,1605);ctx.moveTo(1820,1605);ctx.lineTo(2810,1605);ctx.stroke();
  rect(1120,1598,700,10,t>=465&&t<475?'rgba(77,149,125,.5)':'rgba(169,87,82,.42)');
  for(let i=0;i<5;i++){rect(1260+i*105,805,72,13,'#f6e7be');rect(1260+i*105,960,72,13,'#f6e7be')}label('RANG 4e B',1515,780,24,'#fff5d1');

  for(let n of npcs){let q=npcPosition(n);if(q&&!obstacles.some(o=>inBox(q.x,q.y,o))){if(n.adult)adultPerson(q.x,q.y,n);else person(q.x,q.y,n.c,n.hair,n.name)}}
}

const westFloor=new Image();westFloor.src='batiment-ouest.png';const bFloor=new Image();bFloor.src='batiment-b.png';
function drawDoor(r,d,open){ctx.save();ctx.translate(d.x,d.y);const h=['top','bottom'].includes(r.side);ctx.fillStyle='#d6c09a';ctx.strokeStyle='#634936';ctx.lineWidth=2;if(h){ctx.fillRect(-25,-8,50,16);ctx.strokeRect(-25,-8,50,16);ctx.fillStyle='#503b30';ctx.fillRect(-21,-5,42,10);ctx.fillStyle='#9b7049';ctx.fillRect(open?2:-20,open?-19:-4,open?7:40,open?38:8);ctx.strokeStyle='#d7b987';ctx.lineWidth=1.5;ctx.strokeRect(open?2:-20,open?-19:-4,open?7:40,open?38:8);ctx.fillStyle='#ebd49f';ctx.beginPath();ctx.arc(open?6:15,open?-8:0,1.8,0,Math.PI*2);ctx.fill()}else{ctx.fillRect(-8,-25,16,50);ctx.strokeRect(-8,-25,16,50);ctx.fillStyle='#503b30';ctx.fillRect(-5,-21,10,42);ctx.fillStyle='#9b7049';ctx.fillRect(open?-19:-4,open?2:-20,open?38:8,open?7:40);ctx.strokeStyle='#d7b987';ctx.lineWidth=1.5;ctx.strokeRect(open?-19:-4,open?2:-20,open?38:8,open?7:40);ctx.fillStyle='#ebd49f';ctx.beginPath();ctx.arc(open?-8:0,open?6:15,1.8,0,Math.PI*2);ctx.fill()}ctx.restore()}
function indoor(){if(westFloor.complete&&westFloor.naturalWidth)ctx.drawImage(westFloor,0,0,INSIDE.w,INSIDE.h);else rect(0,0,INSIDE.w,INSIDE.h,'#bba987');for(const r of rooms){if(r.label){let [top,bottom,x,y,w,h]=r.label;rect(x,y,w,h,'#f2eddf');label(top,x+w/2,y+19,15,'#203748');label(bottom,x+w/2,y+37,14,'#203748')}let d=roomDoor(r),allowed=r.open||(flags.key&&!['life','library'].includes(r.id));drawDoor(r,d,allowed)}let patrol=patrolAt(t),pos=patrolPosition(t);if(patrol&&pos)adultPerson(pos.x,pos.y,npcs.find(n=>n.id===patrol.id));if(flags.inRoom){let n=rooms.find(r=>r.id===flags.inRoom);if(n)person(player.x,player.y,'#e6a34a','#3d2b2c','TOI',true)}}
function northInterior(){if(bFloor.complete&&bFloor.naturalWidth)ctx.drawImage(bFloor,0,0,INSIDE_NORTH.w,INSIDE_NORTH.h);else rect(0,0,INSIDE_NORTH.w,INSIDE_NORTH.h,'#cfbd9e');for(const r of bRooms){let d=roomDoor(r),allowed=r.id==='cpe'||(r.id==='canteen'&&['midiBefore','lunchRank','lunchMeal','midiAfter'].includes(phaseAt(t)))||(flags.key&&!['canteen','cpe'].includes(r.id));drawDoor(r,d,allowed)}let patrol=patrolAt(t),pos=patrolPosition(t);if(patrol&&pos)adultPerson(pos.x,pos.y,npcs.find(n=>n.id===patrol.id))}
function render(){ctx.clearRect(0,0,W,H);let c=camera();ctx.save();ctx.scale(c.s,c.s);ctx.translate(-c.x,-c.y);if(scene==='inside')indoor();else if(scene==='insideNorth')northInterior();else outside();person(player.x,player.y,'#e6a34a','#3d2b2c','TOI',true);if(Math.hypot(player.tx-player.x,player.ty-player.y)>4){ctx.strokeStyle='#ffe18c';ctx.lineWidth=4;ctx.beginPath();ctx.arc(player.tx,player.ty,15,0,7);ctx.stroke()}ctx.restore()}
function drawMap(){let d=devicePixelRatio,w=mc.width=mc.clientWidth*d,h=mc.height=mc.clientHeight*d;if(!w||!h)return;mx.clearRect(0,0,w,h);let inBuilding=scene.startsWith('inside'),world=scene==='insideNorth'?INSIDE_NORTH:scene==='inside'?INSIDE:WORLD,list=scene==='insideNorth'?bRooms:scene==='inside'?rooms:zones,s=Math.min((w-35)/world.w,(h-35)/world.h),ox=(w-world.w*s)/2,oy=(h-world.h*s)/2;mx.fillStyle=inBuilding?'#67797a':'#648d72';mx.fillRect(ox,oy,world.w*s,world.h*s);if(scene==='outside'&&courtyardFloor.complete&&courtyardFloor.naturalWidth)mx.drawImage(courtyardFloor,ox,oy,world.w*s,2000*s);if(scene==='inside'&&westFloor.complete&&westFloor.naturalWidth)mx.drawImage(westFloor,ox,oy,INSIDE.w*s,INSIDE.h*s);else if(scene==='insideNorth'&&bFloor.complete&&bFloor.naturalWidth)mx.drawImage(bFloor,ox,oy,INSIDE_NORTH.w*s,INSIDE_NORTH.h*s);for(let z of list){let known=(scene==='insideNorth'?northKnown:scene==='inside'?indoorKnown:discovered).has(z.id);mx.fillStyle=known?'#dfbd8f99':'#344e5899';mx.fillRect(ox+z.x*s,oy+z.y*s,z.w*s,z.h*s);mx.strokeStyle='#173744';mx.lineWidth=2;mx.strokeRect(ox+z.x*s,oy+z.y*s,z.w*s,z.h*s);mx.fillStyle=known?'#163846':'#bed2d1';mx.font=`bold ${Math.max(12,14*d)}px Trebuchet MS`;mx.textAlign='center';mx.fillText(known?z.name:'???',ox+(z.x+z.w/2)*s,oy+(z.y+z.h/2)*s)}mx.fillStyle='#ffdd74';mx.beginPath();mx.arc(ox+player.x*s,oy+player.y*s,Math.max(7,8*d),0,7);mx.fill();mc._map={s,ox,oy,d,list}}
mc.addEventListener('mousemove',e=>{let m=mc._map;if(!m)return;let b=mc.getBoundingClientRect(),x=(e.clientX-b.left)*m.d,y=(e.clientY-b.top)*m.d,z=[...m.list].reverse().find(z=>x>=m.ox+z.x*m.s&&x<=m.ox+(z.x+z.w)*m.s&&y>=m.oy+z.y*m.s&&y<=m.oy+(z.y+z.h)*m.s),known=z&&(scene==='insideNorth'?northKnown:scene==='inside'?indoorKnown:discovered).has(z.id);$('#mapInfo').innerHTML=z?`<h3>${known?z.name:'???'}</h3><p>${known?z.info:'Zone inconnue. Explore pour en savoir plus.'}</p><small>Le temps est en pause.</small>`:'<h3>Survole une zone</h3><p>Le point jaune indique ta position.</p>'});
function tick(now){parentSummons();if(lateRun){let f=Math.min(1,(now-lateRun.start)/2200);let points=[{x:lateRun.x,y:lateRun.y},{x:1470,y:1640},{x:1470,y:1400},{x:1500,y:1110}];let segment=Math.min(2,Math.floor(f*3)),u=Math.min(1,f*3-segment);player.x=points[segment].x+(points[segment+1].x-points[segment].x)*u;player.y=points[segment].y+(points[segment+1].y-points[segment].y)*u;player.tx=player.x;player.ty=player.y;if(f>=1){lateRun=null;incidentOpen=false;notify('Tu es dans la cour. Rejoins le rang avant 8 h.')}}if(incidentOpen&&!lateRun&&!incidentDialogShown&&now-incidentStarted>1450){incidentDialogShown=true;$('#incident').classList.add('open')}let dt=Math.min(.05,(now-last)/1000||0);last=now;if(started&&!ended&&!mapOpen&&!profileOpen&&!relationsOpen&&!servicesOpen&&!rumorsOpen&&!dialogOpen&&!classActive&&!incidentOpen){let timeRate=['recre1','recre2'].includes(phaseAt(t))?.10:phaseAt(t).startsWith('midi')?.34:.48;t+=dt*timeRate;let p=phaseAt(t);transition(p);updateHUD();let dx=player.tx-player.x,dy=player.ty-player.y,d=Math.hypot(dx,dy);if(d>2){let step=Math.min(d,player.speed*dt),nx=player.x+dx/d*step,ny=player.y+dy/d*step;if(canTraverse(player.x,player.y,nx,ny)){player.x=nx;player.y=ny}else{player.tx=player.x;player.ty=player.y;target=null}}if(player.route?.length&&Math.hypot(player.tx-player.x,player.ty-player.y)<7){let a=player.route.shift();player.tx=a.x;player.ty=a.y}if(target&&!player.route?.length&&Math.hypot(player.tx-player.x,player.ty-player.y)<7){let a=target;target=null;if(a.type==='enter')enter(a.wing);if(a.type==='exitNorthInterior'){scene='outside';player.x=2180;player.y=770;player.tx=player.x;player.ty=player.y;notify('Tu ressors dans la cour par le bâtiment B.')}if(a.type==='exitWest'){scene='outside';player.x=1550;player.y=770;player.tx=player.x;player.ty=player.y;notify('Tu ressors par l’aile ouest.')}if(a.type==='npc')talk(a.obj);if(a.type==='room')roomAction(a.obj)}if(scene==='outside'){for(let z of zones)if(player.x>=z.x&&player.x<z.x+z.w&&player.y>=z.y&&player.y<z.y+z.h)discovered.add(z.id);if(['rang1','rang2','rang3'].includes(p)&&player.y<790&&player.x>2200&&now-(flags.lastObservation||0)>10000){addObservation();flags.lastObservation=now;notify('Un surveillant te voit loin du rang : observation !')}}else{if(scene==='inside'){for(let r of rooms){let d=roomDoor(r);if(Math.hypot(player.x-d.x,player.y-d.y)<165)indoorKnown.add(r.id)}}else if(scene==='insideNorth')northKnown.add('northHall');let patrol=patrolAt(t),pos=patrolPosition(t);if(patrol&&pos&&t>=720&&t<840&&Math.hypot(player.x-pos.x,player.y-pos.y)<300&&!flags.observedPatrol){flags.observedPatrol=true;verify('patrol',patrol.id==='surv',patrol.id==='surv'?'Tu as vu Jef dans l’aile est à midi.':'Tu as vu '+npcs.find(n=>n.id===patrol.id).name+' faire cette ronde.')}if(patrol&&pos&&(flags.inRoom?Math.hypot(player.x-pos.x,player.y-pos.y)<300:(scene==='insideNorth'?player.y>=245&&player.y<=321:player.x>=285&&player.x<=357)&&Math.hypot(player.x-pos.x,player.y-pos.y)<110)&&!dialogOpen)caughtByPatrol(npcs.find(n=>n.id===patrol.id))}if(t>=1020&&!ended)finish()}if(now>toastUntil)$('#toast').style.display='none';render();requestAnimationFrame(tick)}resize();updateHUD();requestAnimationFrame(tick);
